from review_schema import A

A('3:2.1','Siesta — Bijapur','P',{'Composition':'A reclining figure at lower right is surrounded by three attendants beneath branching trees; an expansive blue floral border encloses the small scene.','Perspective Convention':'The reclining body, carpet and vessels occupy a shallow tilted ground; distant pale buildings rise above dense foliage rather than sharing one rigorous vanishing point.','Palette & Pigment':'Orange-red clothing and green foliage contrast with blue and gold-coloured framing; these are observed colours, not pigment analysis.','Motifs & Hidden Details':'A standing attendant at left holds a large red fan or fly-whisk-like object and extends a white cloth; cups and vessels line the foreground. Small buildings are partly hidden in the upper foliage.'},'persianate floral-trade',sig='political=The accompanying argument links shared cultural practices with political aesthetics.|visual/aesthetic=Luxury is conveyed through layered textiles, service and garden setting.',dist='The scene illustrates the lecture’s Persianate-world discussion; it is not documentary proof that every depicted object was imported from Persia.')
for refs,title,desc,other in [('3:3.1,4.1','Mahmud Gawan Madrasa','The surviving multi-storey façade has repeated pointed openings, blue tile bands and a tall cylindrical corner minaret. The courtyard view reveals a large central arched recess opposite the viewer.','Ulugh Beg Madrasa and the Registan comparison'),('3:4.2','Ulugh Beg Madrasa and the Registan comparison','The photograph encompasses several buildings around Registan Square: monumental rectangular portals with recessed pointed arches, slender towers and extensive coloured geometric surfaces. The caption singles out Ulugh Beg Madrasa; it does not name every building in the view.','Mahmud Gawan Madrasa')]:
 A(refs,title,'A',{'Building Type & Function':'Madrasa, a place of learning, identified by the caption.','Elevation & Massing':desc,'Structural System':'Arcuate openings and monumental arched portal forms are visible; exact vault construction and hidden room plans are not established.','Ornament Vocabulary':'Tile-like blue and contrasting geometric bands articulate vertical towers and horizontal façade zones.','Paired Comparison':'Slide 4 explicitly connects Bidar and Timurid Central Asia through the paired madrasa views.'},'persianate trabeate-arcuate tilework iwan',sig='regional-identity=The lecture places Deccani architecture within a wider Persianate network.|visual/aesthetic=Portals, towers and coloured surfaces provide concrete points of comparison.',dist='The comparison establishes affinity, not proof that the two buildings have identical plans or one directly copies every part of the other.',compare=[{'target':other,'relationship':'parallel','reason':'Explicit Bidar–Samarkand pairing on slide 4.'}])
A('3:5.1','Well south of Takht Mahal','A',{'Building Type & Function':'Water structure within Bidar Fort, captioned fifteenth–sixteenth century.','Plan & Spatial Organization':'A partly visible rounded basin meets a masonry wall with a tall pointed recess and smaller side openings. The structure sits below the surrounding ground level.','Structural System':'Masonry retaining walls and pointed recesses are visible; the image does not establish the full hydraulic system.','Materials & Construction Technique':'Dark block masonry and lighter lining meet the water surface.'},'water-gardens persianate',sig='religious/cosmological=The heading invokes the garden of paradise.|political=Landscape transformation joins water provision to the palace setting.',dist='The visible well is not itself a complete chahar-bagh plan; the slide connects water infrastructure and garden planning at a broader scale.')
A('3:5.2','Bahmani basin at Bidar Fort','A',{'Plan & Spatial Organization':'A lobed basin fills the foreground; straight garden paths and hedges lead toward the palace ruins beyond. The mosque lies to the right.','Building Type & Function':'Water basin in a palace and mosque setting.','Structural System':'The low shaped basin is distinct from the vaulted buildings around it.','Ornament Vocabulary':'Repeated projections around the basin turn a functional water edge into a geometric outline.'},'water-gardens chahar-bagh',sig='visual/aesthetic=Water, paths and architecture structure a coordinated landscape.|religious/cosmological=The lecture proposes paradise imagery as part of garden design.',dist='The present landscaped photograph does not independently date every hedge or path to the Bahmani period.')
A('3:5.3','Sola Khamba Masjid in the Bidar landscape','A',{'Building Type & Function':'Mosque behind the Bahmani basin, named in the slide caption.','Elevation & Massing':'A long rhythm of pointed arches leads to a large domed mass at the right of the photograph.','Structural System':'Arches and a dome provide an arcuate vocabulary; the interior support count cannot be verified from this exterior.','Plan & Spatial Organization':'The building bounds one side of the larger court and water-garden view.'},'water-gardens trabeate-arcuate',sig='visual/aesthetic=The long arcade gives a boundary and rhythm to the landscape composition.',dist='Do not infer a complete mosque plan or count of supports merely from the building’s name.')
A('3:6.1','Sailabchi basin — Bidriware','M',{'Form & Function':'A broad fluted basin sits above a rounded lower body. A pierced central cover with knob occupies the centre.','Technique':'The lecture contrasts zinc-alloy Bidriware and inlay with Iranian copper engraving. Bright metallic motifs stand against a dark ground; exact alloy proportions are not supplied.','Decorative Vocabulary':'Pointed petal-shaped lobes radiate around the bowl; repeated pale leaf forms continue on the lower body.'},'bidri ghalamzani',sig='social=Materials and skilled surface work matter alongside artistic appearance.|economic/trade=The slide explicitly treats everyday objects as trade goods.',dist='Inlay inserts a contrasting material; engraving cuts the surface. They are not synonyms.',compare=[{'target':'Iranian ghalamzani lidded vessel','relationship':'parallel','reason':'Slide 6 compares materials and techniques while preserving their difference.'}])
A('3:6.2','Iranian ghalamzani lidded vessel','M',{'Form & Function':'A rounded lidded vessel has a short foot and tall bud-like finial. The precise use is not captioned.','Technique':'Ghalamzani names the Iranian metalworking process; the slide emphasizes engraving and copper, not the Bidriware zinc-alloy inlay of the paired basin.','Decorative Vocabulary':'Dense scrolls surround figural panels on the body and lid. Highlights and dark incisions structure the surface.'},'ghalamzani bidri',sig='visual/aesthetic=Engraved figural and scrolling fields cover the vessel continuously.|regional-identity=The Iranian technique is compared with a regional Deccani one.',dist='Ghalamzani is a technique label, not this vessel’s individual title.',compare=[{'target':'Sailabchi basin — Bidriware','relationship':'parallel','reason':'Explicit technical comparison on slide 6.'}])
A('3:7.1','Uncaptioned miniature detail — turbaned man','P',{'Composition':'A bearded man in a pale high turban and ochre patterned outer garment fills the frame; pale architecture lies at left and dense green foliage behind.','Figural Style':'The face turns slightly left; jewellery and a hilt-like object appear at the chest.','Line & Hand':'The video thumbnail is too blurred for painter attribution or fine brushwork assessment.'},'persianate',sig='visual/aesthetic=The close crop introduces miniature painting through facial and textile detail.',dist='A video thumbnail without a caption cannot be assigned to Farrukh Beg merely because his portrait appears on the next slide.',uncertain=['Artist, sitter, date and original object uncaptioned.'])
A('3:8.1,25.1','Self-Portrait of Farrukh Beg — lecture identification','P',{'Composition':'A single elderly standing figure occupies a narrow dark garden field surrounded by nested decorated and inscribed borders.','Figural Style':'White beard, yellow turban, long ochre coat and a staff or cane emphasize age and upright bearing; one hand rises near the face.','Text–Image Relationship':'Calligraphy runs around the inner image and below it; the borders belong to an album-page presentation. No translation is inferred from the small script.','Motifs & Hidden Details':'Flowering branches frame the head and shoulders; a thin blue-white sky band appears at the top of the inner image.'},'muraqqa persianate craft-agency',sig='social=The lecture makes the painter himself visible and discusses the honorific Beg.|regional-identity=The stated itinerary links Shiraz, the Mughal atelier and Bijapur.',dist='The self-portrait designation and possible Jahangir-period date are lecture identifications, not conclusions available from facial appearance alone.')
A('3:9.1','Ibrahim Adil Shah riding Atash Khan','P',{'Composition':'A large richly caparisoned elephant dominates the lower centre; riders sit above, a smaller elephant overlaps at right, and dense flowering trees rise behind.','Perspective Convention':'Overlapping animals and high-set distant rocks create layered depth without a single-point architectural grid.','Figural Style':'The ruler is differentiated by position, dress and elaborate elephant trappings. The caption identifies Atash Khan, Chanchal and a European figure; it does not securely map every name to a visible small figure.','Motifs & Hidden Details':'A deer-like animal stands in the upper-right clearing; small birds and water-edge details appear below it; floral branches arch over the elephant.','Palette & Pigment':'Dark elephant bodies, bright pink blossoms, green ground and gold-coloured cloth create the main contrasts.'},'animal-motifs royal-devotion persianate',sig='political=The ruler’s appearance with a named royal elephant makes authority visible.|visual/aesthetic=The animal’s scale and luxuriant setting turn court identity into a landscape spectacle.',dist='The presence of a captioned European figure does not make the whole work European in technique.',compare=[{'target':'Goddess Sarasvati enthroned — Bijapur','relationship':'complementary','reason':'The paired image repeats the ruler and elephant in a small upper panel.'}])
A('3:9.2','Goddess Sarasvati enthroned — Bijapur','P',{'Composition':'The seated goddess occupies a large golden throne under a canopy. Winged attendants flank its upper sides; a small panel of ruler and elephant crowns the composition.','Figural Style':'Jewellery, looping pale drapery and a profile face distinguish the central figure; a standing figure at lower right approaches the throne.','Motifs & Hidden Details':'A peacock stretches across the bottom; blue-and-white vases with flowers stand beside the throne; small birds sit near the backrest; two white birds flank a tiny figure in the lowermost medallion.','Text–Image Relationship':'Small script appears on the throne steps and beneath the top panel; it is not translated here.','Perspective Convention':'Angled throne edges and stacked compartments combine several spatial conventions rather than one continuous room.'},'sarasvati animal-motifs halo-angels porcelain',sig='religious/cosmological=An Indic goddess appears in a Bijapur courtly image.|political=The ruler-and-elephant panel links patronal authority to the sacred scene.|visual/aesthetic=Winged attendants, ceramic vases and elaborate throne forms combine several visual vocabularies.',dist='The image’s subject and its borrowed visual motifs are separate questions; a Hindu subject does not mean every motif or technique has one cultural origin.',compare=[{'target':'Ibrahim Adil Shah riding Atash Khan','relationship':'complementary','reason':'The upper panel connects the paired royal and sacred images.'}])
A('3:10.1','Page from Kitab-e-Nauras','P',{'Composition':'Several lines of dark calligraphy occupy pale cartouches above a large red vase filled with curling stems. Narrow coloured rules frame the page.','Text–Image Relationship':'Writing is the principal content; floral illumination integrates the text with the lower vase rather than illustrating a narrative episode.','Palette & Pigment':'Gold-coloured ground, red vase and black script dominate; the photograph alone cannot distinguish leaf from powdered metallic paint.','Motifs & Hidden Details':'Small flowers and pale birds are dispersed through the illuminated ground.'},'calligraphy floral-trade',sig='political=The page is captioned as made for Ibrahim Adil Shah II.|visual/aesthetic=Illumination binds textual and vegetal forms into a single page.',dist='Kitab-e-Nauras is a named text; the photographed decorative page is not a transcription or translation of its contents.',compare=[{'target':'Sangeet Mahal at Nauraspur','relationship':'complementary','reason':'The lecture pairs literary-musical patronage and its architectural setting.'}])
A('3:10.2','Sangeet Mahal at Nauraspur','A',{'Building Type & Function':'The named musical palace/hall at Nauraspur, introduced with Kitab-e-Nauras.','Structural System':'A broad pointed arch and narrow flanking pointed openings dominate a massive masonry façade.','Elevation & Massing':'The surviving rectangular block has a flat upper edge; deep openings and exposed interior walls make its ruined condition visible.','Materials & Construction Technique':'Weathered stone or masonry surfaces and traces of lighter finish are visible; the original roof is not reconstructed from this view.'},'trabeate-arcuate persianate',sig='political=The pairing connects the ruler’s cultural interests to a built site.|visual/aesthetic=Large central and slender side openings create a clear façade hierarchy.',dist='The surviving ruin does not justify inventing its original acoustic performance or a complete roof design.',compare=[{'target':'Page from Kitab-e-Nauras','relationship':'complementary','reason':'Explicit pairing on slide 10.'}])
A('3:11.1','Ibrahim Adil Shah II playing the tambur','P',{'Composition':'The ruler sits in the lower painted panel with a long-necked instrument across his lap, attendants at lower left and one standing figure at right. Two small monochrome European prints are mounted above.','Text–Image Relationship':'A narrow calligraphic strip sits above the assembled images; a large floral border with birds surrounds the entire album page.','Motifs & Hidden Details':'The instrument’s rounded body rests near the ruler’s right knee. Blossoming trees occupy the green background; small birds dot the outer gold-coloured border.','Perspective Convention':'The central seated figure is larger than the attendants; patterned surfaces and shallow layered space take precedence over a unified vanishing point.'},'muraqqa persianate',sig='political=The lecture places this Deccani ruler’s portrait in a collection at Shah Jahan’s court.|visual/aesthetic=Album mounting deliberately juxtaposes colour painting and monochrome print.',dist='The painting’s maker and the later album assembler need not be the same person; collecting a work is not commissioning its original production.')
for row,title,detail in [(2,'European print above the tambur portrait — left','A kneeling figure outdoors faces rays descending from a cloud; trees and ground are rendered through dark lines.'),(3,'European print above the tambur portrait — right','A haloed kneeling figure occupies an interior with a table and classical column; clouds and rays enter from above.')]:
 A(f'3:11.{row}',title,'R',{'Composition & Motifs':detail,'Process':'Captioned European print; fine black lines are visible, but no exact process or artist is supplied.','Edition & Circulation':'Mounted above the painted musician-ruler and collected at Shah Jahan’s court, according to the lecture.'},'muraqqa halo-angels',sig='visual/aesthetic=The upper monochrome panels contrast with the coloured Deccani image below.|social=The album records collecting and rearrangement across cultural boundaries.',dist='Do not assign a specific saint, printmaker or engraving date to this uncaptioned component.',uncertain=['Individual print subject, maker and process unresolved.'])
A('3:12.1','Yogini with a Mynah bird','P',{'Composition':'A single woman stands amid oversized flowering plants; rocks, trees and pale buildings rise behind her. Multiple calligraphic borders surround the image.','Figural Style':'A high hair knot, orange robe, jewellery and a bird held near the face coexist, making the lecture’s ascetic-versus-royalty question understandable.','Perspective Convention':'High horizon, stacked terrain and enlarged foreground plants create layered rather than single-point depth.','Motifs & Hidden Details':'The small bird rests on her raised hand at left of her face; pink flowers flank her body, with long curling leaves on the right.','Text–Image Relationship':'Calligraphic panels frame the scene but are not translated in the lecture.'},'yogini-andal porcelain muraqqa',sig='religious/cosmological=The lecture asks whether the figure recalls Andal or a woman mendicant.|visual/aesthetic=Jewelled courtliness and ascetic markers make identification deliberately open.',dist='Andal, royalty and a Chinese-porcelain source for foliage are questions in the slide, not settled attributions.')
A('3:13.1','Modern paper-marbling demonstration','F',{'Subject':'Hands lift a sheet from a shallow tray of blue, green and yellow swirls; commercial bottles stand behind it.','Studio or Documentary Context':'Modern craft-process photograph used to explain marbling, not a photograph of a seventeenth-century workshop.','What It Is Evidence Of':'Transfer of a floating or surface-borne coloured pattern to paper is demonstrated. The foamy-looking bath does not establish the historical materials used in Deccani abri.'},'abri craft-agency',sig='social=Process knowledge helps explain an otherwise difficult-to-read historical surface.',dist='The contemporary tutorial illustrates a principle; its recipe cannot be projected unchanged into early modern practice.')
A('3:13.2,14.2,25.2;8:20.2','Ascetic Riding a Nag','P',{'Composition':'An emaciated rider on an emaciated horse crosses a dense field of flowing marbled bands. Angular ribs and limbs remain legible against the swirling background.','Line & Hand':'Dark fine outlines and repeated rib lines articulate the bodies; the marbled field has a different, fluid pattern logic.','Motifs & Hidden Details':'The rider extends a thin rod toward upper left; the horse droops its head. Its vertebrae and ribs are exaggerated, connecting human and animal bodily frailty.','Palette & Pigment':'The caption specifies ink, opaque watercolour and gold on marbled paper. Pale bodies contrast with black, cream, red and greenish bands.','Perspective Convention':'No conventional landscape recession; the surface pattern surrounds the figures.','Subject Matter vs Technique Origin':'The ascetic subject and Sufi interpretive vocabulary are distinct from the abri process, whose travel through China, Timurid Persia and India is proposed in the lecture.'},'abri nafs-majnun',sig='religious/cosmological=Slide 14 invokes the lower self and Sufi metaphors of life and death.|visual/aesthetic=Controlled figural outlines contrast with fluid marbling.|regional-identity=The Deccani example participates in the lecture’s account of travelling techniques.',dist='Nag here means an old or worn horse, not a naga serpent.|The lecture’s stencil question is not proof that a particular stencil was used.',compare=[{'target':'Thin rider on a marbled horse — comparison image','relationship':'parallel','reason':'Slide 14 contrasts placement of marbling within the horse and around the figures.'}])
A('3:14.1','Thin rider on a marbled horse — comparison image','P',{'Composition':'An angular, thin rider sits on a left-facing horse against a mostly plain warm ground. Marbling is concentrated within the horse’s body.', 'Line & Hand':'Rider contours and ribs are drawn; a red bridle and rod contrast with the mottled horse.', 'Perspective Convention':'The isolated side view has no deep landscape.', 'Motifs & Hidden Details':'The rider’s raised rod, projecting ribs and bent legs parallel the adjacent composition, but the surrounding field is largely unpatterned.'},'abri nafs-majnun',sig='visual/aesthetic=The comparison reveals that marbling can be reserved inside a silhouette as well as spread across a background.',dist='The two images are separate objects or versions, not merely a colour-adjusted crop of one work.',compare=[{'target':'Ascetic Riding a Nag','relationship':'parallel','reason':'Explicit similarities-and-differences comparison on slide 14.'}],uncertain=['Left image has no separate title, maker or date.'])
A('3:15.1','Bijapur — circular city plan','A',{'Plan & Spatial Organization':'A roughly rounded fortified perimeter encloses a smaller citadel. Roads connect several gates; the urban fabric is uneven rather than a perfect geometric circle.', 'Building Type & Function':'City map used to discuss Deccani urban planning.', 'Structural System':'The plan locates monuments but does not reveal their spanning systems.'},'cartography circular-city',sig='regional-identity=The heading asks whether circular planning recalls Kakatiya precedents.',dist='Reference to Kakatiyas is a question; resemblance of rounded plans does not prove direct derivation.')
A('3:16.1','Gol Gumbaz','A',{'Building Type & Function':'A monumental tomb; the section diagram names Sultan Muhammad Adil Shah.', 'Plan & Spatial Organization':'A large square chamber is flanked by corner towers. The diagram includes a lower view of underground vaults and a separate arch-support plan.', 'Structural System':'Eight intersecting arches support the dome according to the lecture and diagram: an arcuate system, not a forest of post-and-lintel supports.', 'Elevation & Massing':'A very large bulbous dome dominates a cubic base; octagonal corner towers have repeated galleries and smaller domed caps.', 'Ornament Vocabulary':'Pointed façade arches, dome-base arcade and parapet details emphasize scale transitions.', 'Materials & Construction Technique':'The photograph and drawing expose massing and support geometry, not a complete material specification.'},'trabeate-arcuate dome whispering-gallery',sig='political=Monumental tomb scale participates in dynastic representation.|visual/aesthetic=The contrast between the huge central dome and slender stacked towers creates the silhouette.',dist='The lecture calls it second largest, but that ranking lacks a measurement category and is not repeated as an independently verified global fact.|A whispering chamber concerns acoustic transmission, not proof of a double-shell dome.')
A('3:17.1','Uncaptioned domed complex — possible Ibrahim Rauza','A',{'Plan & Spatial Organization':'An axial path runs between hedges toward a central gateway. Two separate domed structures stand to either side behind it.', 'Elevation & Massing':'Bulbous domes, slender corner towers and a long low arcade define the skyline.', 'Structural System':'Pointed openings and domes indicate arcuate vocabulary; interior construction is hidden.'},'trabeate-arcuate water-gardens',sig='visual/aesthetic=The approach aligns garden, gateway and paired domed masses.',dist='The index’s likely Ibrahim Rauza identification remains provisional because the slide itself supplies only a video URL.',uncertain=['Site identification remains provisional.'])
A('3:18.1','Dagger with Zoomorphic Hilt — Bijapur','M',{'Form & Function':'A long curved, fluted blade meets an elaborate openwork hilt; the whole object at left is paired with a close-up at centre.', 'Technique':'Engraved gold-coloured surface, openwork and coloured eye insets are visible. The slide does not itself assay the metal or stones.', 'Decorative Vocabulary':'An elephant-like curling trunk occupies the left side; interlocked animal bodies rise vertically; a bird appears at right above a long curling feathered tail. The lecture names yali/elephant and simurgh/phoenix as southern Indian and Persian vocabularies.', 'Subject Matter vs Technique Origin':'This is an Indian dagger whose decorative creatures are read across cultural traditions; motif origin is not identical to manufacture location.'},'yali simurgh animal-motifs',sig='regional-identity=The lecture locates multiple mythic vocabularies within a Bijapur luxury object.|visual/aesthetic=Animals form the usable grip itself, not a separate pictorial panel.',dist='Simurgh and phoenix are comparative labels on the slide; they should not erase differences between traditions or turn every bird-shaped detail into a securely identified species.',compare=[{'target':'Sultan Ali Adil Shah I','relationship':'parallel','reason':'Slide 19 explicitly asks about the portrait’s relationship to the preceding dagger.'}])
A('3:19.1,25.3','Sultan Ali Adil Shah I','P',{'Composition':'A standing profile ruler holds a curved sheet of writing against an intense blue ground; diagonal ornamental bands frame the upper corners.', 'Figural Style':'A high patterned cap, gold-coloured shawl, white pleated robe and long patterned sash create a highly articulated court costume.', 'Motifs & Hidden Details':'A zoomorphic-looking dagger hilt projects at the waist; a circular pendant hangs on the chest; an inscription runs vertically at right.', 'Perspective Convention':'The ground is largely flat; volume is concentrated in dress folds and the figure’s profile.'},'yali royal-devotion',sig='political=The slide connects the portrait and dagger to Vijayanagara–Bijapur relations and Talikota.|visual/aesthetic=The ornate weapon is embedded in a full courtly costume.',dist='The portrait does not prove that the sitter owned the exact museum dagger shown on the previous slide.',compare=[{'target':'Dagger with Zoomorphic Hilt — Bijapur','relationship':'parallel','reason':'Explicit cross-object comparison of weapon and court portrait.'}])
A('3:20.1','House of Bijapur','P',{'Composition':'A large central enthroned figure is surrounded by seated figures on a carpet; a separate lower strip contains attendants and a white horse. Pink hills and dark water occupy the upper landscape.', 'Perspective Convention':'The carpet is tilted toward the viewer while figures remain upright; dynastic ordering takes precedence over a single optical viewpoint.', 'Figural Style':'Different turbans, robes, beards and dagger hilts distinguish the assembled courtly figures. The lecture discusses lineage, not a documentary group sitting.', 'Motifs & Hidden Details':'A green parasol stands above the central throne; additional canopies span the background; a small boat-like mark appears on the distant water, whose identification as the Arabian Sea is posed as a question.', 'Palette & Pigment':'Pink terrain, green canopies, blue carpet and gold-coloured ornament form contrasting bands.'},'silsila chakravartin persianate',sig='political=The assembly constructs dynastic lineage; the lecture also recalls Bijapur’s fall in 1686.|religious/cosmological=The royal umbrella is linked in the lecture to Chakravartin imagery.|visual/aesthetic=Costume and dagger differences coexist within one ordered dynastic field.',dist='The 1680 painting is not an eyewitness image of the 1686 fall.|The Arabian Sea reading is tentative, and the gathering need not depict a historically simultaneous meeting.')
A('3:21.1','Hyderabad or Bagh-nagar — 1854 city map','A',{'Plan & Spatial Organization':'The map shows the city south of a river, with a regular street grid and highlighted building footprints. The lecture centres the reading on Charminar.', 'Building Type & Function':'An urban plan used to explain an adaptation of the chahar-bagh model.', 'Paired Comparison':'The right photograph converts the map’s axis into a street view through Char Kaman toward Charminar.'},'chahar-bagh cartography',sig='political=The city’s organizing centre gives monumental form to urban authority.|visual/aesthetic=Garden-derived ordering is discussed at the scale of a city.',dist='An 1854 map records the city at that time; it is not automatically the original foundation plan or proof of four intact gardens.')
A('1:24.2;3:21.2','Charminar','A',{'Plan & Spatial Organization':'Module 3 shows Charminar in the distance through a foreground Char Kaman gateway; the two structures must be distinguished.', 'Structural System':'Large pointed arches are the main visible spanning vocabulary. The close detail in Module 1 shows bracketed projections and nested arch mouldings.', 'Elevation & Massing':'Tall minarets rise beyond the foreground gateway; the close-up reveals stacked ornamented façade bands.', 'Ornament Vocabulary':'Round floral medallions, pendant bud-like forms, repeated brackets and dense stucco borders articulate the façade.', 'Syncretism':'The explicit comparison is with Lotus Mahal’s stucco, demonstrating a shared regional ornamental discussion.'},'stucco trabeate-arcuate chahar-bagh',sig='regional-identity=The lecture compares ornament across Hampi and Hyderabad.|political=Charminar supplies the central reference for the city-planning discussion.',dist='The large foreground arch in Module 3 slide 21 is Char Kaman, not the whole Charminar.',compare=[{'target':'Lotus Mahal','relationship':'parallel','reason':'Module 1 slide 24 explicitly juxtaposes the stucco.'}])
A('3:22.1','Portrait of Khawwas-Khan in Witsen’s album','P',{'Composition':'A half-length profile figure stands behind a low patterned parapet against a pale green ground. Narrow floral borders surround the portrait.', 'Figural Style':'Turban, patterned sleeveless outer garment and a hand on a sword hilt make the military/courtly role visible; a tiny sprig is held in the other hand.', 'Text–Image Relationship':'Number 42 appears above the frame; handwritten European-language annotations sit below. The lecture identifies a Portuguese inscription and Witsen’s album.', 'Motifs & Hidden Details':'The sword descends centrally; the small flower or sprig at right balances the weapon visually.'},'habshi album-collecting',sig='social=The caption identifies an Abyssinian commander, foregrounding African participation in Deccani political society.|economic/trade=The lecture links portrait collecting to the VOC at Machilipatnam.|political=Military rank and court identity are represented in a portrait later collected overseas.',dist='Khawwas-Khan is not Malik Anbar; African origin does not make the two historical figures interchangeable.')
A('3:23.1','Adoration of the Christ Child — Golconda','P',{'Composition':'The infant lies centrally in a cradle, surrounded by kneeling and standing figures; airborne winged figures occupy the top. An elaborate blue-and-gold-coloured border encloses the dark floral field.', 'Figural Style':'The woman beside the cradle and the infant have radiating halos. Several lower figures wear strongly patterned or contrasting local-looking clothes.', 'Motifs & Hidden Details':'Two hovering figures above carry objects or garlands; another long-winged attendant stands behind the cradle. Vessels and offerings lie below; a row of small white waterbirds occupies the very bottom.', 'Perspective Convention':'The cradle is oblique but the figures are stacked in a shallow field rather than a unified Renaissance room.', 'Subject Matter vs Technique Origin':'Christian narrative appears in a Golconda painting with Persianate borders, textile-like ground and locally adapted figures.'},'halo-angels christian-adaptation animal-motifs muraqqa',sig='religious/cosmological=Christian narrative is reimagined in a Qutb Shahi context.|visual/aesthetic=Border, costume, wings and floral ground make adaptation materially visible.',dist='Christian subject matter does not make this a European-made painting or prove conversion of its patron.',compare=[{'target':'Interior of Badshahi Ashurkhana','relationship':'parallel','reason':'Slide 23 pairs ornamental and cultural amalgamation across painting and interior.'}])
A('3:23.2','Interior of Badshahi Ashurkhana','A',{'Building Type & Function':'Ashurkhana interior in Hyderabad, a Shi‘i commemorative setting rather than an ordinary secular hall.', 'Structural System':'Visible posts support horizontal ceiling members. Painted or tiled pointed niches on the walls are not themselves proof of load-bearing arches.', 'Ornament Vocabulary':'Blue, green and gold-coloured tile fields, calligraphic ornament and pointed compartments cover the rear and side walls.', 'Plan & Spatial Organization':'A railing encloses the central display of standards; suspended lamps and a chandelier hang between the foreground posts.', 'Motifs & Locations':'Hand-shaped and round standards stand at the rear; they belong to the ritual furnishing, not the wall’s structural system.'},'tilework ashurkhana calligraphy',sig='religious/cosmological=Standards and commemorative setting make religious use visible.|visual/aesthetic=Patterned wall compartments create a rich counterpart to the paired manuscript border.',dist='The juxtaposition with the Adoration does not turn this interior into a Christian church.',compare=[{'target':'Adoration of the Christ Child — Golconda','relationship':'parallel','reason':'Explicit paired slide on cultural and ornamental amalgamation.'}])
A('3:24.1','Avium Vivae Icones — Collaert bird engraving','R',{'Process':'The caption identifies engraving: a line-based intaglio print.', 'Composition & Motifs':'Two large parrots occupy the foreground. The left bird bends toward something held near its beak; a village and much smaller animals recede between the birds.', 'Edition & Circulation':'Antwerp, about 1600, with British Museum accession Z,1.59 given by the lecture.', 'Subject Matter vs Technique Origin':'A European bird print is compared with a Golconda painted parrot; the media remain distinct.'},'engraving animal-motifs',sig='visual/aesthetic=The comparison isolates bird pose and image circulation across different picture conventions.',dist='A similar parrot pose is not by itself enough to prove the painting copied this exact impression.',compare=[{'target':'Parrot on a mango tree with a tethered ram','relationship':'parallel','reason':'Slide 24 juxtaposes bird images; direct derivation is not explicitly demonstrated.'}])
A('3:24.2','Parrot on a mango tree with a tethered ram','P',{'Composition':'An oversized red-and-green parrot perches above a much smaller ram beside the tree trunk. The sparse turquoise ground isolates the forms.', 'Perspective Convention':'Hierarchy and juxtaposition replace naturalistic relative scale; the parrot is deliberately enormous beside the ram.', 'Motifs & Hidden Details':'Yellow fruits dot the mango foliage; the parrot raises a dark claw toward its beak; a red tether runs from the ram’s neck toward a peg at lower left.', 'Palette & Pigment':'Bright red plumage, green wing and turquoise field contrast with the pale ram; dye or pigment names cannot be inferred.'},'animal-motifs',sig='visual/aesthetic=The scale mismatch and borrowed-looking bird pose create a hybrid pictorial arrangement.',dist='Do not read the relative sizes as zoological measurement or infer the exact source print from resemblance alone.',compare=[{'target':'Avium Vivae Icones — Collaert bird engraving','relationship':'parallel','reason':'Explicit lecture juxtaposition.'},{'target':'Dervish receiving guests','relationship':'parallel','reason':'Both paintings appear beside the engraving on slide 24.'}])
A('3:24.3','Dervish receiving guests','P',{'Composition':'The shown detail groups people beside a masonry platform beneath a fruiting tree; the crop omits the full composition.', 'Figural Style':'A bearded figure in pale clothing stands beside a blue-toned ascetic with a yellow lower garment.', 'Motifs & Hidden Details':'A white bird perches high on the wall. Hand-shaped and round calligraphic standards rise near the tree; a small golden vessel sits on the masonry ledge.', 'Perspective Convention':'Tree, platform and figures overlap in a compressed shallow field.'},'animal-motifs ashurkhana',sig='religious/cosmological=The dervish subject and standards connect the scene to devotional life.|visual/aesthetic=Bird imagery is compared across engraving and miniature painting.',dist='The blue-toned figure’s exact identity is not given; skin colour alone does not securely identify a deity.',compare=[{'target':'Parrot on a mango tree with a tethered ram','relationship':'parallel','reason':'Grouped in the lecture’s cross-cultural bird comparison.'}])
A('','Persianate cosmopolis','C',{'Definition':'In the lecture’s use of Emma Flatt, Persianate culture involves shared language practice and political aesthetics across regions, while allowing exchange and conflict.', 'Nearest Confusable Terms':'Persianate is broader than Persian nationality or manufacture in Iran. Shared practice does not imply one ethnicity, one religion or political harmony.', 'Applied To':'Bijapur’s Siesta, travelling artists, Bidar’s madrasa and Deccani objects provide the module’s cases.'},'persianate connected-histories',dist='A Persianate object can be made in the Deccan by locally active artisans; the term is not a provenance label.',slides='3:1,2,4,6,8')
